\title{Cryptography from Chaos:\\ Exact Structure of the Logistic Keystream}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
The logistic map $f(x) = 4x(1-x)$ on the unit interval is the canonical example of
one-dimensional chaos, and it has repeatedly been proposed as the heart of a
``chaos-based'' stream cipher: the orbit of a secret seed $x_0 \in (0,1)$ is used as a
keystream that masks the plaintext. Two properties are advertised as the source of
security: \emph{sensitive dependence on initial conditions} (the avalanche effect), and
\emph{algebraic depth} (the $n$-th iterate is a polynomial of exponentially large degree
$2^n$, so recovering the seed appears to require solving a degree-$2^n$ equation). We make
both claims precise and prove them. The unifying device is the exact
\emph{semiconjugacy of the logistic map to angle doubling},
$f(\sin^2 t) = \sin^2(2t)$, which lifts to $f^n(\sin^2 t) = \sin^2(2^n t)$ for every $n$.
From this single identity we derive: (i) an explicit family of seeds converging to the
fixed point $0$ whose $n$-th iterates remain a \emph{constant} distance $\tfrac12$ from the
fixed orbit, a quantitative avalanche; and (ii) the fact that the $n$-th iterate, viewed
as a polynomial, has degree exactly $2^n$, with the polynomial and dynamical descriptions
agreeing pointwise. We also record the invariant structural facts (the unit interval is
preserved; the only real fixed points are $0$ and $3/4$). Finally we explain, using the
conjugacy, why the naive chaos cipher is nonetheless insecure: in the conjugate coordinate
the dynamics is the binary shift map, so the degree-$2^n$ barrier is an artifact of
coordinates and the seed is recoverable in time linear in the security parameter.
\end{abstract}

\section{Introduction}

Chaos and cryptography share a slogan: small causes, large effects. A cryptosystem is
supposed to \emph{diffuse} information so that a one-bit change in the key or plaintext
changes roughly half the output bits. A chaotic dynamical system exhibits \emph{sensitive
dependence on initial conditions}, so that a small change in the state is amplified
exponentially in time. The resemblance has inspired a long line of ``chaos-based''
ciphers, of which the simplest and most famous uses the logistic map at its fully chaotic
parameter.

\paragraph{The logistic cipher.} Fix a secret seed $x_0 \in (0,1)$ and iterate
$f(x) = 4x(1-x)$. The keystream is the orbit
$K = (f(x_0), f^2(x_0), f^3(x_0), \dots)$, quantized to bits; the ciphertext is
$C = M \oplus K$ for plaintext $M$. Decryption regenerates $K$ from $x_0$ and XORs it out.
The proposed security rests on two claims:
\begin{enumerate}
  \item \textbf{Sensitivity.} A change of $\varepsilon$ in $x_0$ produces an $O(1)$ change
    in $f^n(x_0)$ after $n = O(\log(1/\varepsilon))$ iterations.
  \item \textbf{Algebraic depth.} The iterate $f^n$ is a polynomial of degree $2^n$, so
    solving for $x_0$ from keystream values is a degree-$2^n$ root-finding problem,
    exponential in $n$.
\end{enumerate}

\paragraph{Contribution.} We prove precise forms of both claims and identify the exact
structural reason they hold. The keystone is the classical semiconjugacy
\[
  f(\sin^2 t) = \sin^2(2t), \qquad\text{hence}\qquad f^n(\sin^2 t) = \sin^2(2^n t),
\]
which conjugates the logistic map to the angle-doubling map $t \mapsto 2t$. The per-step
stretching factor $2$ is the common origin of the Lyapunov exponent $\log 2$, the
exponential sensitivity, and the degree growth. We then use the same identity to explain
the cipher's fatal weakness: doubling is the binary shift, so the keystream transparently
emits the bits of the conjugate coordinate.

\section{Definitions and elementary invariants}

\begin{definition}[Logistic map]
The \emph{logistic map} at the fully chaotic parameter $r = 4$ is
$f : \R \to \R$, $f(x) = 4x(1-x)$. Its $n$-fold iterate is written $f^n$, with
$f^0 = \mathrm{id}$.
\end{definition}

Two immediate values anchor the dynamics on the boundary: $f(0) = 0$ and $f(1) = 0$.

\begin{proposition}[Invariance of the unit interval]
If $0 \le x \le 1$ then $0 \le f(x) \le 1$.
\end{proposition}
\begin{proof}
Nonnegativity is clear since $x \ge 0$ and $1 - x \ge 0$ give $f(x) = 4x(1-x) \ge 0$. For
the upper bound, $1 - f(x) = 1 - 4x(1-x) = (2x-1)^2 \ge 0$, so $f(x) \le 1$.
\end{proof}

\begin{proposition}[Fixed points]
For $x \in \R$, $f(x) = x$ if and only if $x = 0$ or $x = \tfrac34$.
\end{proposition}
\begin{proof}
The equation $4x(1-x) = x$ is equivalent to $x(3 - 4x) = 0$, whose roots are $0$ and $3/4$.
\end{proof}

Since $f(0) = 0$, the entire orbit of $0$ is constantly $0$: $f^n(0) = 0$ for all $n$.

\section{Semiconjugacy to angle doubling}

\begin{theorem}[Semiconjugacy]
For every $t \in \R$, $\; f(\sin^2 t) = \sin^2(2t)$.
\end{theorem}
\begin{proof}
Using $\sin(2t) = 2\sin t \cos t$ and $\cos^2 t = 1 - \sin^2 t$,
\[
  \sin^2(2t) = 4\sin^2 t\,\cos^2 t = 4\sin^2 t\,(1 - \sin^2 t) = f(\sin^2 t). \qedhere
\]
\end{proof}

The map $\Phi(t) = \sin^2 t$ intertwines the doubling map $D(t) = 2t$ with $f$:
$f \circ \Phi = \Phi \circ D$. Since $\Phi$ is surjective onto $[0,1]$, this is a genuine
semiconjugacy, and it lifts to all iterates.

\begin{theorem}[Iterated semiconjugacy]
For every $n \in \N$ and $t \in \R$, $\; f^n(\sin^2 t) = \sin^2(2^n t)$.
\end{theorem}
\begin{proof}
Induction on $n$. For $n = 0$ both sides equal $\sin^2 t$. Assuming the claim for $k$,
\[
  f^{k+1}(\sin^2 t) = f\bigl(\sin^2(2^k t)\bigr) = \sin^2\bigl(2 \cdot 2^k t\bigr)
    = \sin^2\bigl(2^{k+1} t\bigr). \qedhere
\]
\end{proof}

\begin{remark}
Under $x = \sin^2 t$ the logistic dynamics is exactly $t \mapsto 2^n t$. The multiplier
$2^n$ is the exact stretching factor; its logarithm per step, $\log 2$, is the Lyapunov
exponent. Every subsequent result is a shadow of this one identity.
\end{remark}

\section{Algebraic depth: the degree-$2^n$ theorem}

\begin{definition}[Logistic polynomial and its iterates]
Let $P(X) = 4X(1-X) \in \R[X]$, and define the composition iterates by $P^{[0]} = X$ and
$P^{[n+1]} = P \circ P^{[n]}$.
\end{definition}

\begin{lemma}
$\deg P = 2$.
\end{lemma}
\begin{proof}
$P = 4X - 4X^2$ has leading term $-4X^2$.
\end{proof}

\begin{theorem}[Exponential algebraic degree]
For every $n \in \N$, $\; \deg P^{[n]} = 2^n$.
\end{theorem}
\begin{proof}
Induction on $n$. For $n = 0$, $\deg X = 1 = 2^0$. Since degrees multiply under composition
of polynomials over a field,
\[
  \deg P^{[k+1]} = (\deg P)(\deg P^{[k]}) = 2 \cdot 2^k = 2^{k+1}. \qedhere
\]
\end{proof}

\begin{theorem}[Algebraic $=$ dynamical]
For every $n \in \N$ and $x \in \R$, $\; P^{[n]}(x) = f^n(x)$.
\end{theorem}
\begin{proof}
Induction on $n$. For $n = 0$ both sides are $x$. For the step,
$P^{[k+1]}(x) = P(P^{[k]}(x)) = P(f^k(x)) = 4 f^k(x)(1 - f^k(x)) = f^{k+1}(x)$.
\end{proof}

\begin{remark}
Given a keystream sample $y = f^n(x_0)$, recovering $x_0$ algebraically means solving
$P^{[n]}(x) = y$, of degree $2^n$. For $n = 64$ the degree is
$2^{64} \approx 1.8\times10^{19}$. Section~6 shows why this barrier is illusory.
\end{remark}

\section{Sensitive dependence on initial conditions}

\begin{definition}[Sensitivity seeds]
For $n \in \N$ set $\; s_n = \sin^2\!\bigl(\pi/2^{\,n+2}\bigr)$.
\end{definition}

\begin{lemma}[Positivity]
$s_n > 0$ for all $n$.
\end{lemma}
\begin{proof}
The angle $\alpha_n = \pi/2^{\,n+2}$ satisfies $0 < \alpha_n < \pi$, so $\sin\alpha_n > 0$
and $s_n = \sin^2\alpha_n > 0$.
\end{proof}

\begin{lemma}[Quadratic collapse]
$s_n \le (\pi/2^{\,n+2})^2$, hence $s_n \to 0$ as $n \to \infty$.
\end{lemma}
\begin{proof}
With $\alpha_n = \pi/2^{\,n+2} \in [0,\pi]$ we have $0 \le \sin\alpha_n \le \alpha_n$;
squaring gives $s_n \le \alpha_n^2 \to 0$.
\end{proof}

\begin{lemma}[Exact landing point]
For every $n$, $\; f^n(s_n) = \tfrac12$.
\end{lemma}
\begin{proof}
By the iterated semiconjugacy with $t = \pi/2^{\,n+2}$,
\[
  f^n(s_n) = \sin^2\!\Bigl(2^n \cdot \tfrac{\pi}{2^{\,n+2}}\Bigr)
    = \sin^2\!\Bigl(\tfrac{\pi}{4}\Bigr) = \tfrac12. \qedhere
\]
\end{proof}

\begin{theorem}[Quantitative sensitive dependence]
For every $n \in \N$,
\[
  0 < s_n \le \Bigl(\tfrac{\pi}{2^{\,n+2}}\Bigr)^2
  \qquad\text{and}\qquad
  \bigl| f^n(s_n) - f^n(0)\bigr| = \tfrac12.
\]
\end{theorem}
\begin{proof}
The bounds on $s_n$ are the previous two lemmas. For the gap, $f^n(0) = 0$ and
$f^n(s_n) = \tfrac12$, so the absolute difference is exactly $\tfrac12$.
\end{proof}

\begin{remark}
The seeds $s_n$ are exponentially close to the fixed point $0$ (distance $O(2^{-2n})$) yet
after only $n$ iterations they are separated from the fixed orbit by a constant $\tfrac12$.
A perturbation of size $\varepsilon \approx 2^{-2n}$ becomes macroscopic after
$n \approx \tfrac12\log_2(1/\varepsilon)$ steps.
\end{remark}

\section{Cryptographic consequences}

\subsection{The two pillars are real theorems}
The sensitivity theorem confirms the avalanche; the degree theorem confirms the
exponential algebraic degree (and the algebraic$=$dynamical theorem certifies that the
polynomial computes the dynamics). A designer reading only these results would conclude the
seed is well hidden.

\subsection{The conjugate coordinate breaks the cipher in linear time}
Write angles as fractions of a half-turn: $t = \pi\theta$, $x = \sin^2(\pi\theta)$ with
$\theta \in [0,1)$. Under this coordinate the doubling map becomes the \emph{binary shift}
$\theta \mapsto 2\theta \pmod 1$. Writing $\theta = 0.b_1 b_2 b_3\ldots$ in base $2$, each
iteration deletes the leading bit: $0.b_1 b_2 b_3\ldots \mapsto 0.b_2 b_3 b_4\ldots$. Thus
the keystream, in the conjugate coordinate, reads out the successive bits of $\theta$. An
attacker recovers $n$ bits of $\theta$ from $O(n)$ samples with $O(n)$ arithmetic. The
degree-$2^n$ polynomial is \emph{not} a hardness barrier; it is an artifact of the
coordinate $x$. Conjugacy linearizes the apparent nonlinearity and collapses the
exponential to a shift. The break runs in time linear in the security parameter.

\subsection{Sensitivity is double-edged}
In $p$-bit arithmetic the factor $2^n$ per $n$ steps decorrelates a computed orbit from the
ideal orbit after $\approx p$ steps, so the numerical period and the sensitivity horizon
coincide. Moreover, transported through the conjugacy the invariant distribution of $f$ is
the arcsine law $d\mu = dx/(\pi\sqrt{x(1-x)})$, not uniform, so a raw logistic keystream is
statistically biased toward the endpoints of $[0,1]$.

\section{Discussion and future directions}

The results form a compact bridge between real dynamics and polynomial algebra: a single
trigonometric identity yields both a dynamical statement (quantitative sensitive
dependence) and an algebraic statement (degree exactly $2^n$). The cryptographic upshot is
a clean case study in coordinate-dependent hardness: the naive logistic cipher looks strong
in $x$ and is trivial in $\theta$.

\begin{enumerate}
  \item \emph{Linear-time cryptanalysis, as a theorem.} Establish rigorously that the
    conjugate-coordinate attack recovers the seed to $n$ bits from $O(n)$ keystream
    samples with $O(n)$ arithmetic.
  \item \emph{The invariant density is the arcsine law and is unique.} Prove that
    $d\mu = dx/(\pi\sqrt{x(1-x)})$ is $f$-invariant, is the pushforward of the uniform
    measure on the doubling circle under $t \mapsto \sin^2(\pi t)$, and is the unique
    absolutely continuous invariant measure.
  \item \emph{A matching decryption-instability lower bound.} Show that $2^n$ controls both
    the divergence rate from above and the precision-loss rate from below, so a $p$-bit
    implementation loses correlation with the true orbit after exactly $p$ steps.
\end{enumerate}

\end{document}

