"""Demo: the exact semiconjugacy f^n(sin^2 t) = sin^2(2^n t)."""
from __future__ import annotations
import math


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def logistic_iterate(x: float, n: int) -> float:
    for _ in range(n):
        x = logistic(x)
    return x


def verify_semiconjugacy(num_points: int = 9, max_n: int = 10) -> float:
    max_err = 0.0
    for i in range(1, num_points + 1):
        t = math.pi * i / (num_points + 1)
        for n in range(max_n + 1):
            lhs = logistic_iterate(math.sin(t) ** 2, n)
            rhs = math.sin((2 ** n) * t) ** 2
            max_err = max(max_err, abs(lhs - rhs))
    return max_err


if __name__ == "__main__":
    err = verify_semiconjugacy()
    print(f"max |f^n(sin^2 t) - sin^2(2^n t)| = {err:.2e}")
    print(f"identity holds to machine precision: {err < 1e-9}")

"""Demo: quantitative sensitive dependence of the logistic map.

Seeds s_n = sin^2(pi/2^(n+2)) shrink to the fixed point 0 (distance O(2^-2n)),
yet f^n(s_n) = 1/2 exactly, a constant gap of 1/2 from the orbit of 0.
"""
from __future__ import annotations
import math


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def logistic_iterate(x: float, n: int) -> float:
    for _ in range(n):
        x = logistic(x)
    return x


def sensitivity_seed(n: int) -> float:
    return math.sin(math.pi / 2 ** (n + 2)) ** 2


def sensitivity_table(max_n: int = 14) -> list[tuple[int, float, float, float]]:
    rows = []
    for n in range(1, max_n + 1):
        s = sensitivity_seed(n)
        bound = (math.pi / 2 ** (n + 2)) ** 2
        gap = abs(logistic_iterate(s, n) - logistic_iterate(0.0, n))
        rows.append((n, s, bound, gap))
    return rows


if __name__ == "__main__":
    for n, s, bound, gap in sensitivity_table():
        print(f"n={n:>2}  s_n={s:.3e}  bound={bound:.3e}  gap={gap:.4f}")

