from __future__ import annotations
from fractions import Fraction


def _trim(p: list[Fraction]) -> list[Fraction]:
    while len(p) > 1 and p[-1] == 0:
        p = p[:-1]
    return p


def poly_mul(a: list[Fraction], b: list[Fraction]) -> list[Fraction]:
    """Multiply two polynomials given as coefficient lists (index = power of X)."""
    out = [Fraction(0)] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            out[i + j] += ai * bj
    return _trim(out)


def poly_compose(outer: list[Fraction], inner: list[Fraction]) -> list[Fraction]:
    """Return outer(inner(X)) via Horner's method."""
    result: list[Fraction] = [Fraction(0)]
    for coeff in reversed(outer):
        result = poly_mul(result, inner)
        result[0] += coeff
    return _trim(result)


def logistic_iterate_degree(n: int) -> int:
    """Degree of the n-th composition iterate of P(X) = 4X - 4X^2; returns 2^n.

    Composing polynomials multiplies their degrees, so the degree doubles each
    step. Complexity is dominated by symbolic composition, O(4^n) coefficient ops.
    """
    p = [Fraction(0), Fraction(4), Fraction(-4)]
    result: list[Fraction] = [Fraction(0), Fraction(1)]
    for _ in range(n):
        result = poly_compose(p, result)
    return len(result) - 1
